mapper.select:
SELECT 
FROM articles
WHERE deleted = 0
  AND author_id = #{authorId}
  AND status = 1
  AND publish_time IS NOT NULL

    AND (publish_time < #{cursorTime}
         OR (publish_time = #{cursorTime} AND id < #{cursorId}))

ORDER BY publish_time DESC, id DESC
LIMIT #{limit}

SELECT 
FROM articles
WHERE deleted = 0
  AND author_id = #{authorId}
  AND status = #{status}

    AND (created_at < #{cursorTime}
         OR (created_at = #{cursorTime} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT 
FROM articles
WHERE deleted = 0
  AND author_id = #{authorId}

    AND status = #{status}


    AND (updated_at < #{cursorTime}
         OR (updated_at = #{cursorTime} AND id < #{cursorId}))

ORDER BY updated_at DESC, id DESC
LIMIT #{limit}
